    if(kind==='contact'){const l=find('leads',id);l.attempts??=[];l.attempts.push({at:now,outcome:v.outcome,note:v.note,actorId:l.ownerId});if(v.outcome==='已接通'){l.contactAt??=now;l.status='contacted';}closeDialog();save(v.outcome==='已接通'?'聯絡紀錄已儲存。':'已記下聯絡嘗試，線索仍留在待聯絡清單。');openLead(id);}
    if(kind==='case'){const sourceLead=find('leads',v.leadId),sourceOpp=find('opportunities',v.oppId);if(sourceLead?.caseId||sourceOpp?.caseId){closeDialog();return openCase(sourceLead?.caseId||sourceOpp.caseId);}const amount=Number(v.amount);if(!Number.isFinite(amount)||amount<0)return toast('請填入有效案件金額。',true);if(v.stage==='lost')return toast('新案件請先選擇進行中階段，再記錄流失原因。',true);const c={id:uid('c'),code:`BL-${new Date().getFullYear()}-${String(db.cases.length+1).padStart(3,'0')}`,title:v.title.trim(),client:v.client.trim(),phone:sourceLead?.phone||'',type:v.type,storeId:v.storeId,ownerId:v.ownerId,projectId:v.projectId||null,unitIds:f.getAll('unitIds'),stage:v.stage,amount,createdAt:now,updatedAt:now,nextStep:v.nextStep,nextAt:isoDate(v.nextAt),opportunityId:sourceOpp?.id||null,wonAt:v.stage==='won'?now:null};db.cases.unshift(c);if(sourceLead){sourceLead.caseId=c.id;sourceLead.status='converted';sourceLead.storeId=c.storeId;sourceLead.ownerId=c.ownerId;}if(sourceOpp){sourceOpp.caseId=c.id;sourceOpp.status='converted';db.visits.filter(x=>x.opportunityId===sourceOpp.id).forEach(x=>{if(!x.caseIds.includes(c.id))x.caseIds.push(c.id);});db.tasks.filter(t=>t.opportunityId===sourceOpp.id&&t.status==='todo').forEach(t=>t.status='done');}event(c.id,'案件已建立',sourceLead?'從線索接續立案。':sourceOpp?'從既有洽談接續立案，保留立案前拜訪。':'開始追蹤這個新機會。','create',sourceOpp?.id);if(activeCase(c))replaceTask({caseId:c.id,storeId:c.storeId,ownerId:c.ownerId,title:c.nextStep,dueAt:c.nextAt});closeDialog();ui.page='cases';location.hash='cases';save('案件已建立，紀錄已接續。');openCase(c.id);}
